'use strict';
const cards=window.CARDS||[], byId=new Map(cards.map(c=>[String(c.id),c]));
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'Common':'Común','Rare':'Rara','Super Rare':'Súper Rara','Ultra Rare':'Ultra Rara','Secret Rare':'Secreta'};
const types={'Ritual Monster':'Monstruo de ritual','Ritual Effect Monster':'Monstruo de ritual y efecto','Toon Monster':'Monstruo Toon','Normal Monster':'Monstruo normal','Effect Monster':'Monstruo de efecto','Flip Effect Monster':'Monstruo de volteo','Fusion Monster':'Monstruo de fusión','Spell Card':'Carta mágica','Trap Card':'Carta de trampa'};
const attrs={DARK:'Oscuridad',LIGHT:'Luz',EARTH:'Tierra',WATER:'Agua',FIRE:'Fuego',WIND:'Viento',DIVINE:'Divinidad'};
const races={Dragon:'Dragón',Spellcaster:'Lanzador de Conjuros',Warrior:'Guerrero','Beast-Warrior':'Guerrero-Bestia',Beast:'Bestia','Winged Beast':'Bestia Alada',Fiend:'Demonio',Fairy:'Hada',Insect:'Insecto',Dinosaur:'Dinosaurio',Reptile:'Reptil',Fish:'Pez','Sea Serpent':'Serpiente Marina',Aqua:'Aqua',Pyro:'Piro',Thunder:'Trueno',Rock:'Roca',Plant:'Planta',Machine:'Máquina',Zombie:'Zombi',Normal:'Normal',Equip:'Equipo',Field:'Campo',Continuous:'Continua',Counter:'Contraefecto','Quick-Play':'Juego Rápido',Ritual:'Ritual'};
const SETS=[{id:'LOB',name:'Legend of Blue Eyes White Dragon',es:'La leyenda del Dragón Blanco',hero:'Blue-Eyes White Dragon',subtitle:'El origen de la leyenda.'},{id:'MRD',name:'Metal Raiders',es:'Invasores de Metal',hero:'Summoned Skull',subtitle:'El poder de los invasores.'},{id:'SRL',name:'Spell Ruler',es:'Señor de la Magia',hero:'Relinquished',subtitle:'Dominá el poder de la magia.'}];
const BOX=window.BoxEngine;
const key='dragon-vault-boxes-v4',previousV3Key='dragon-vault-boxes-v3',previousKey='dragon-vault-boxes-v2',oldKey='dragon-vault-lob-v1';let state={version:4,coins:1000,owned:{},packs:0,decks:[],odds:[70,18,10,2],boxes:{},selectedSet:'LOB'}, view='sobres',currentDeck=null,lastPack=[];
function activeSet(){return SETS.find(s=>s.id===state.selectedSet)||SETS[0];}
function activeBox(){return state.boxes[activeSet().id];}

function validate(s){if(!s||![1,2,3,4].includes(s.version)||!s.owned||typeof s.owned!=='object'||Array.isArray(s.owned)||!Number.isSafeInteger(s.packs)||s.packs<0||!Array.isArray(s.decks)||s.decks.length>200||!Array.isArray(s.odds)||s.odds.length!==4||s.odds.some(n=>!Number.isFinite(n)||n<0)||Math.abs(s.odds.reduce((a,b)=>a+b,0)-100)>.001)throw Error('Formato de copia no válido.');for(const [id,n]of Object.entries(s.owned))if(!byId.has(id)||!Number.isSafeInteger(n)||n<0||n>1e7)throw Error('La copia contiene cartas o cantidades no válidas.');const ids=new Set();for(const d of s.decks){if(!d||typeof d.id!=='string'||ids.has(d.id)||typeof d.name!=='string'||d.name.length>60||!d.cards||typeof d.cards!=='object'||Array.isArray(d.cards))throw Error('Mazo no válido.');ids.add(d.id);for(const[id,n]of Object.entries(d.cards))if(!byId.has(id)||!Number.isInteger(n)||n<1||n>3||n>(s.owned[id]||0))throw Error('El mazo supera las cartas disponibles.');const counts=deckCounts(d);if(counts.main>60||counts.extra>15)throw Error('El mazo supera su tamaño máximo.');}if(s.version===1){s={...s,version:4,boxes:Object.fromEntries(SETS.map(set=>[set.id,BOX.create(cards,set.id)])),selectedSet:'LOB'};}else{if(!s.boxes||Array.isArray(s.boxes)||Object.keys(s.boxes).length!==SETS.length||!SETS.some(set=>set.id===s.selectedSet))throw Error('Las cajas del archivo no son válidas.');for(const set of SETS){if(s.version===2||s.version===3)s.boxes[set.id]=BOX.migrate(s.boxes[set.id],cards,set.id,s.version);BOX.validate(s.boxes[set.id],cards,set.id);}s.version=4;}if(s.coins===undefined)s.coins=1000;if(!Number.isSafeInteger(s.coins)||s.coins<0||s.coins>1e9)throw Error('Saldo de monedas no válido.');s.economy=window.Economy.validate(s.economy,cards);return s;}
state.economy=window.Economy.defaults(cards);
for(const set of SETS)state.boxes[set.id]=BOX.create(cards,set.id);
try{const saved=localStorage.getItem(key)||localStorage.getItem(previousV3Key)||localStorage.getItem(previousKey)||localStorage.getItem(oldKey);if(saved)state=validate(JSON.parse(saved));}catch(e){setTimeout(()=>toast('No se pudo cargar el guardado. Podés importar una copia.'),500);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch(e){toast('No se pudo guardar en el navegador. Exportá una copia.');}updateStats();}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function updateStats(){$('#coinBalance').textContent=state.coins.toLocaleString('es-AR');const unique=Object.values(state.owned).filter(n=>n>0).length,total=Object.values(state.owned).reduce((a,b)=>a+b,0);$('#unique').textContent=`${unique} / ${cards.length}`;$('#total').textContent=total;$('#navCount').textContent=unique;$('#packs').textContent=state.packs;$('#deckCount').textContent=state.decks.length;const p=Math.round(unique/cards.length*100)||0;$('#completion').textContent=`${p}% completado`;$('#progressFill').style.width=p+'%';renderBox();}
function image(c){return c.image||`images/${c.id}.jpg`;}
function tile(c,i=0,reveal=false){return `<button class="card ${rarityClass(c)} ${state.owned[c.id]?'':'unowned'} ${reveal?'reveal':''}" style="animation-delay:${i*.065}s" data-card="${c.id}" aria-label="Ver ${esc(c.name_es)}"><img src="${esc(image(c))}" loading="lazy" alt="${esc(c.name_en)}"><span class="copies">${state.owned[c.id]||0}×</span><span class="card-name">${esc(c.name_es)}</span><small class="${c.rarity==='Common'?'':'rarity'}">${esc(names[c.rarity]||c.rarity)} · ${esc(c.code)}</small></button>`;}
function showView(v){if(!['sobres','coleccion','mazos','iniciales','tienda','catalogo','especiales'].includes(v))throw Error('Sección no válida');view=v;if(v==='sobres'){$('#boxDetail').hidden=true;$('#boxTabs').hidden=false;}for(const name of ['sobres','coleccion','mazos','iniciales','tienda','catalogo','especiales'])$('#'+name).hidden=name!==v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#pageTitle').textContent={tienda:'Una carta puede cambiar tu mazo.',catalogo:'Todas las cartas, a tu alcance.',especiales:'Creá tu próxima sorpresa.',sobres:'Toda leyenda empieza con un sobre.',coleccion:'Tu colección, carta a carta.',iniciales:'Tus primeros compañeros de duelo.',mazos:'De la colección al duelo.'}[v];$('#pageIntro').textContent={tienda:'Comprá cartas puntuales con tus monedas.',catalogo:'Consultá, seleccioná y prepará nuevos productos.',especiales:'Elegí el contenido, las cantidades y el precio.',sobres:'Descubrí las cartas que lo empezaron todo.',coleccion:'Explorá las expansiones y los mazos de inicio. Tocá una carta para leer su ficha en español.',iniciales:'Los mazos originales de Yugi y Kaiba, carta por carta.',mazos:'Armá tus mazos con las cartas que conseguiste.'}[v];if(v==='tienda')renderShop();if(v==='catalogo')renderCatalog();if(v==='especiales')renderCustomPacks();if(v==='iniciales')renderStarters();if(v==='coleccion')renderCollection();if(v==='mazos')renderDecks();}
function collectionFilters(prefix=""){const selected=name=>Array.from(document.querySelectorAll('#'+prefix+'collectionFilters input[name="'+name+'"]:checked')).map(e=>e.value);const f={search:$('#'+prefix+'search').value,set:$('#'+prefix+'setFilter').value,rarity:$('#'+prefix+'rarityFilter').value,onlyOwned:$('#'+prefix+'onlyOwned').checked,ownership:$('#'+prefix+'ownership').value,searchEffect:$('#'+prefix+'searchEffect').checked,sort:$('#'+prefix+'sortBy').value,direction:$('#'+prefix+'sortDirection').value};for(const name of ['attributes','races','categories','types','properties'])f[name]=selected(name);for(const name of ['atk','def','level','copies'])for(const edge of ['Min','Max'])f[name+edge]=$('#'+prefix+''+name+edge).value;return f;}
function renderCollection(){const result=window.CollectionQuery(cards,state.owned,collectionFilters());$('#filterError').textContent=result.error;$('#listCount').textContent=`${result.cards.length} de ${cards.length} cartas · ${result.cards.reduce((n,c)=>n+(state.owned[c.id]||0),0)} copias en tu colección`;$('#collectionGrid').innerHTML=result.cards.length?result.cards.map(c=>tile(filteredPrint(c,$('#setFilter').value))).join(''):'<p>No hay cartas que coincidan. Probá ampliar los rangos o limpiar los filtros.</p>';}
function random(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%n;}
function openPack(){if(packOpening)return [];if(state.coins<5){toast('Necesitás 5 monedas para abrir un sobre.');return [];}const result=sortPack(BOX.draw(activeBox(),random).map(id=>byId.get(id)));if(!result.length){toast('La caja está agotada. Reiniciala para volver a abrir sobres.');return [];}state.coins-=5;for(const c of result)state.owned[c.id]=(state.owned[c.id]||0)+1;state.packs++;lastPack=result;save();showView('sobres');$('#boxDetail').hidden=false;$('#boxTabs').hidden=true;$('#results').hidden=false;$('#packGrid').innerHTML=result.map((c,i)=>tile(c,i,true)).join('');$('#lastSet').textContent=activeSet().name+' · '+result.length+' cartas agregadas';startPackReveal(result);return result.map(c=>({id:c.id,nombre:c.name_es,rareza:names[c.rarity]}));}
function chooseSet(id){if(!SETS.some(s=>s.id===id))return;state.selectedSet=id;$('#results').hidden=true;$('#boxDetail').hidden=false;$('#boxTabs').hidden=true;save();}
function renderBox(){const set=activeSet(),box=activeBox();if(!box)return;const list=cards.filter(c=>c.set===set.id),initial=BOX.initial(cards,set.id),remaining=BOX.total(box),full=Object.values(initial).reduce((a,b)=>a+b,0);$('#boxTabs').innerHTML=SETS.map(s=>`<button data-box="${s.id}" class="${s.id===set.id?'selected':''}" aria-pressed="${s.id===set.id}"><small>EXPANSIÓN ${SETS.indexOf(s)+1} · ${s.id}</small><strong>${esc(s.es)}</strong><span>${Math.ceil(BOX.total(state.boxes[s.id])/BOX.packSize)} sobres restantes</span></button>`).join('');$('#catalogTotal').textContent=list.length;$('.tag').textContent=set.name;$('.pack-info h2').textContent=set.subtitle;$('.edition').textContent=`CAJA ${set.id} · EDICIÓN CLÁSICA`;const hero=list.find(c=>c.name_en===set.hero)||list[0];$('#heroCard').src=image(hero);$('#heroCard').alt=hero.name_en;$('.art-caption').textContent=hero.name_en.toUpperCase();$('#boxRemaining').textContent=remaining+' / '+full;$('#boxPacks').textContent=Math.ceil(remaining/BOX.packSize);$('#boxRound').textContent='Caja '+(box.resets+1);$('#boxFill').style.width=(remaining/full*100)+'%';$('#openPack').disabled=remaining===0||state.coins<5;$('#openPack').innerHTML=remaining?'Abrir un sobre · 5 monedas <span>✦</span>':'Caja agotada';$('#boxStats').innerHTML=Object.keys(names).map(r=>{const group=list.filter(c=>c.rarity===r);return `<div><strong>${group.reduce((n,c)=>n+box.remaining[c.id],0)} / ${group.reduce((n,c)=>n+initial[c.id],0)}</strong><span>${names[r]}</span></div>`;}).join('');renderBoxPool();}
function renderBoxPool(){const set=activeSet(),box=activeBox();if(!box)return;const initial=BOX.initial(cards,set.id);const q=$('#boxSearch').value.toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,''),r=$('#boxRarity').value;let list=cards.filter(c=>c.set===set.id&&(!r||c.rarity===r)&&`${c.name_es} ${c.name_en}`.toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(q));const order={'Secret Rare':0,'Ultra Rare':1,'Super Rare':2,'Rare':3,'Common':4};list.sort((a,b)=>order[a.rarity]-order[b.rarity]||a.code.localeCompare(b.code));$('#boxGrid').innerHTML=list.length?list.map(c=>`<button class="card ${rarityClass(c)} ${box.remaining[c.id]===0?'exhausted':''}" data-card="${c.id}"><img src="${esc(image(c))}" alt="${esc(c.name_en)}" loading="lazy"><span class="copies">${box.remaining[c.id]} / ${initial[c.id]}</span><span class="card-name">${esc(c.name_es)}</span><small class="rarity">${names[c.rarity]}</small><span class="stock-label">${box.remaining[c.id]===0?'AGOTADA':'Quedan '+box.remaining[c.id]+' en la caja'}</span></button>`).join(''):'<p>No hay cartas que coincidan.</p>';}
function resetBox(){const set=activeSet();modal(`<h2>¿Reiniciar ${esc(set.es)}?</h2><p>Se reponen todas las copias de esta caja, incluidas las Ultra Raras y Secretas. Las cartas obtenidas y tus mazos se conservan.</p><button id="confirmReset" class="primary">Reiniciar esta caja</button>`);$('#confirmReset').onclick=()=>{state.boxes[set.id]=BOX.reset(state.boxes[set.id],cards,set.id);save();$('#results').hidden=true;$('#modal').close();toast('Caja repuesta. Tu colección se conserva.');};}
function modal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function detail(id){const c=byId.get(String(id));if(!c)return;modal(`<div class="detail ${rarityClass(c)}"><img src="${esc(image(c))}" alt="${esc(c.name_en)}"><div><span class="tag">${esc(c.code)} · ${esc(names[c.rarity])}</span><h2>${esc(c.name_es)}</h2><div class="english">${esc(c.name_en)}</div><dl><div><dt>Tipo</dt><dd>${esc(types[c.type]||c.type)}</dd></div><div><dt>Valor de venta</dt><dd>${coinValue(c)} monedas · ${esc(names[c.rarity])} de referencia</dd></div><div><dt>En tu colección</dt><dd>${state.owned[c.id]||0} copias</dd></div>${c.attribute?`<div><dt>Atributo · Nivel</dt><dd>${esc(attrs[c.attribute]||c.attribute)} · ${c.level??'—'}</dd></div>`:''}<div><dt>Clase</dt><dd>${esc(races[c.race]||c.race)}</dd></div>${c.atk!=null?`<div><dt>ATK / DEF</dt><dd>${c.atk} / ${c.def}</dd></div>`:''}</dl><p class="effect-label">${c.historical?'Efecto anterior · español':'Descripción de la carta'}</p><p>${esc(c.historical?.text||c.desc_es)}</p>${cardOrigins(c)}${c.historical?`<p class="micro">Traducción del texto inglés de ${esc(c.historical.print)}. No es una transcripción de una edición española.</p><details class="effect-original"><summary>Texto anterior original · inglés</summary><p lang="en">${esc(c.historical.original_en)}</p></details><a class="source-link" href="${esc(c.historical.source)}" target="_blank" rel="noopener">Fuente y edición del texto ↗</a>`:''}${c.historical?'':`<a class="source-link" href="https://www.db.yugioh-card.com/yugiohdb/card_search.action?ope=2&cid=${c.cid}&request_locale=es" target="_blank" rel="noopener">Consultar ficha oficial en español ↗</a>`}<p class="micro">${c.historical?'Usá el efecto clásico de esta ficha. La imagen puede mostrar el texto de una reedición.':'Texto de la base oficial. La imagen puede corresponder a una reedición.'}</p>${state.owned[c.id]?`<button id="removeCard">Vender copias · ${coinValue(c)} monedas c/u</button>`:''}</div></div>`);if(state.owned[c.id])$('#removeCard').onclick=()=>saleDialog(c.id);}
function deckCounts(d){let main=0,extra=0;for(const[id,n]of Object.entries(d.cards)){if(byId.get(id)?.type==='Fusion Monster')extra+=n;else main+=n;}return{main,extra};}
function renderDecks(){renderVisualDecks();}
function changeDeck(id,delta){const d=state.decks.find(d=>d.id===currentDeck),c=byId.get(String(id));if(!d||!c){toast('Elegí una carta primero');return;}const n=(d.cards[id]||0)+delta;if(delta>0){const count=deckCounts(d),fusion=c.type==='Fusion Monster';if(n>3||n>(state.owned[id]||0)){toast('No hay más copias disponibles para este mazo');return;}if((fusion?count.extra:count.main)>=(fusion?15:60)){toast('Alcanzaste el límite de cartas');return;}}if(n<=0)delete d.cards[id];else d.cards[id]=n;save();renderDecks();}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dragon-vault-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){modal('<h2>Tu colección, a salvo.</h2><p>Descargá una copia con tus cartas, mazos y el avance de cada caja. Podés cargarla en otro navegador o dispositivo.</p><div class="backup-actions"><button id="exportData" class="primary">Descargar copia</button><label class="quiet">Elegir copia <input id="importData" type="file" accept=".json,application/json"></label></div><p class="micro">Cargar una copia reemplaza el progreso de este dispositivo. El archivo no incluye imágenes.</p><div id="importReview"></div>');$('#exportData').onclick=exportData;$('#importData').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('El archivo es demasiado grande.');const next=validate(JSON.parse(await f.text()));$('#importReview').innerHTML=`<p>Copia válida: ${Object.values(next.owned).reduce((a,b)=>a+b,0)} cartas y ${next.decks.length} mazos.</p><button id="confirmImport">Reemplazar mi progreso con esta copia</button>`;$('#confirmImport').onclick=()=>{state=next;deletionUndo=null;$('#undoDeletion').hidden=true;currentDeck=null;lastPack=[];$('#results').hidden=true;save();showView(view);$('#modal').close();toast('Copia cargada');};}catch(err){$('#importReview').textContent=err.message;}};}
$('#openPack').onclick=openPack;$('#backup').onclick=backup;$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.box)chooseSet(el.dataset.box);if(el.dataset.view)showView(el.dataset.view);if(el.dataset.card)detail(el.dataset.card);if(el.dataset.deck){currentDeck=el.dataset.deck;renderDecks();}if(el.dataset.minus)changeDeck(el.dataset.minus,-1);if(el.dataset.plus)changeDeck(el.dataset.plus,1);});$('.brand').onclick=e=>{e.preventDefault();showView('sobres');};$('#search').oninput=renderCollection;$('#rarityFilter').onchange=renderCollection;$('#onlyOwned').onchange=renderCollection;$('#setFilter').onchange=renderCollection;$('#boxSearch').oninput=renderBoxPool;$('#boxRarity').onchange=renderBoxPool;$('#resetBox').onclick=resetBox;
$('#newDeck').onclick=()=>{if(state.decks.length>=200){toast('Límite de 200 mazos');return;}const d={id:crypto.randomUUID(),name:`Mi mazo ${state.decks.length+1}`,cards:{}};state.decks.push(d);currentDeck=d.id;save();renderDecks();$('#deckName').focus();};
$('#sources').onclick=()=>modal('<h2>Fuentes y edición</h2><p>Base de datos: mazos de inicio Yugi (SDY) y Kaiba (SDK), edición TCG Norteamérica 2002, 50 cartas fijas cada uno; más Legend of Blue Eyes White Dragon (126), Metal Raiders (144) y Spell Ruler (104). La tercera expansión se publicó originalmente como Magic Ruler; usamos la base de datos con códigos SRL. Rarezas e imágenes en inglés: YGOPRODeck. Nombres y descripciones en español: base oficial de Konami.</p><p>Las fichas históricas sustituyen el efecto actual en los cuatro cambios funcionales confirmados: Sangan, Bruja del Bosque Negro, Tortuga Catapulta y Oscuridad Aproximándose. Son traducciones del efecto TCG anterior, no transcripciones oficiales españolas. En el resto se conserva el texto de la base oficial; la revisión histórica no es exhaustiva. Las imágenes no son necesariamente escaneos de la primera edición. Cajas simuladas con copias limitadas: 500 cartas por caja: 100 sobres de 5. Se mantienen 3 copias de cada rara, 2 de cada súper rara, 1 de cada ultra rara y secreta; el resto se distribuye entre las comunes. No son cajas oficiales de Duel Links ni reproducen sobres físicos.</p><p>Este prototipo guarda el progreso solo en este navegador. No tiene cuentas, intercambios ni sincronización. Exportá copias para conservarlo.</p><p><a class="source-link" href="https://ygoprodeck.com/api-guide/" target="_blank" rel="noopener">YGOPRODeck</a> · <a class="source-link" href="https://www.db.yugioh-card.com/yugiohdb/?request_locale=es" target="_blank" rel="noopener">Base oficial de Konami</a></p>');
$('#rarityFilter').insertAdjacentHTML('beforeend',Object.entries(names).map(([v,n])=>`<option value="${v}">${n}</option>`).join(''));const hero=cards.find(c=>c.name_en==='Blue-Eyes White Dragon');if(hero)$('#heroCard').src=image(hero);$('#boxRarity').insertAdjacentHTML('beforeend',Object.entries(names).map(([v,n])=>`<option value="${v}">${n}</option>`).join(''));updateStats();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_lob_collection',title:'Consultar colección LOB',description:'Lee las cartas obtenidas y los mazos guardados en este dispositivo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No se admiten parámetros');return{cartas:Object.entries(state.owned).map(([id,n])=>({id,nombre:byId.get(id).name_es,copias:n})),mazos:state.decks.map(d=>({nombre:d.name,...deckCounts(d)})),sobres:state.packs};}})).catch(()=>{});}catch{}}

function rarityClass(c){return {'Common':'rarity-common','Rare':'rarity-rare','Super Rare':'rarity-super','Ultra Rare':'rarity-ultra','Secret Rare':'rarity-secret'}[c.rarity]||'rarity-common';}
let deletionUndo=null;
function removeCollectionCards(id,quantity){if(id!==null&&(!byId.has(String(id))||!Number.isInteger(quantity)||quantity<1||quantity>(state.owned[id]||0)))throw Error('Cantidad de copias no válida');deletionUndo=JSON.parse(JSON.stringify({owned:state.owned,decks:state.decks}));if(id===null)state.owned={};else{state.owned[id]-=quantity;if(!state.owned[id])delete state.owned[id];}for(const d of state.decks)for(const cardId of Object.keys(d.cards)){const available=state.owned[cardId]||0;if(!available)delete d.cards[cardId];else d.cards[cardId]=Math.min(d.cards[cardId],available);}deletionUndo.afterOwned=JSON.parse(JSON.stringify(state.owned));deletionUndo.afterDecks=JSON.parse(JSON.stringify(state.decks));$('#results').hidden=true;lastPack=[];save();renderCollection();if(view==='mazos')renderDecks();$('#undoDeletion').hidden=false;}
function confirmRemove(id){const c=byId.get(String(id)),owned=state.owned[id]||0;if(!owned)return;modal(`<h2>Quitar ${esc(c.name_es)}</h2><p>Tenés ${owned} copias. También se ajustarán los mazos que necesiten más copias de las que te queden. La caja no se repone.</p><form id="removeForm"><label>Copias a borrar <input id="removeQuantity" type="number" min="1" max="${owned}" value="1" required></label><div class="delete-actions"><button type="button" id="cancelRemove">Cancelar</button><button class="danger">Borrar copias</button></div></form>`);$('#cancelRemove').onclick=()=>$('#modal').close();$('#removeForm').onsubmit=e=>{e.preventDefault();const n=Number($('#removeQuantity').value);if(!Number.isInteger(n)||n<1||n>(state.owned[id]||0))return;removeCollectionCards(id,n);$('#modal').close();toast('Copias eliminadas. Podés deshacer desde Mi colección.');};}
$('#clearCollection').onclick=()=>{if(!Object.values(state.owned).some(n=>n>0)){toast('Tu colección ya está vacía');return;}modal('<h2>¿Borrar toda tu colección?</h2><p>Se eliminarán todas las cartas obtenidas. Tus mazos conservarán sus nombres, pero quedarán vacíos. Las cajas y el historial de aperturas se mantienen.</p><p>Podés descargar una copia antes de continuar. La última eliminación se puede deshacer mientras esta página siga abierta.</p><div class="delete-actions"><button id="exportBeforeDelete">Descargar copia</button><button id="cancelClear">Cancelar</button><button id="confirmClear" class="danger">Borrar toda mi colección</button></div>');$('#exportBeforeDelete').onclick=exportData;$('#cancelClear').onclick=()=>$('#modal').close();$('#confirmClear').onclick=()=>{removeCollectionCards(null);$('#modal').close();toast('Colección borrada. Podés deshacer esta acción.');};};
$('#undoDeletion').onclick=()=>{if(!deletionUndo)return;for(const[id,n]of Object.entries(deletionUndo.owned))state.owned[id]=(state.owned[id]||0)+Math.max(0,n-(deletionUndo.afterOwned?.[id]||0));for(const old of deletionUndo.decks){const d=state.decks.find(x=>x.id===old.id);if(d&&JSON.stringify(d.cards)===JSON.stringify(deletionUndo.afterDecks.find(x=>x.id===old.id)?.cards))d.cards=old.cards;}deletionUndo=null;$('#undoDeletion').hidden=true;save();renderCollection();toast('Cartas restauradas');};

function setupCollectionFilters(){const groups={attributes:attrs,races:Object.fromEntries(Object.entries(races).filter(([v])=>cards.some(c=>c.type.includes('Monster')&&c.race===v))),categories:{monster:'Monstruos',spell:'Mágicas',trap:'Trampas'},types:Object.fromEntries(Object.entries(types).filter(([v])=>cards.some(c=>c.type===v))),properties:Object.fromEntries(Object.entries(races).filter(([v])=>cards.some(c=>!c.type.includes('Monster')&&c.race===v)))};for(const[group,values]of Object.entries(groups))$('#filter-'+group).innerHTML=Object.entries(values).map(([v,n])=>`<label><input type="checkbox" name="${group}" value="${v}"> ${esc(n)}</label>`).join('');$('#collectionFilters').addEventListener('input',renderCollection);$('#collectionFilters').addEventListener('change',renderCollection);$('#sortBy').onchange=renderCollection;$('#sortDirection').onchange=renderCollection;$('#resetFilters').onclick=()=>{document.querySelectorAll('#collectionFilters input').forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value='';});$('#ownership').value='';$('#search').value='';$('#setFilter').value='';$('#rarityFilter').value='';$('#onlyOwned').checked=false;$('#sortBy').value='code';$('#sortDirection').value='asc';renderCollection();};}
setupCollectionFilters();

$('#backToBoxes').onclick=()=>{$('#boxDetail').hidden=true;$('#boxTabs').hidden=false;};
